fn sorted_key(w: String) -> String {
  return w
    |> split("")
    |> sort_by(|c| c)
    |> join("")
}

fn anagram_groups(words: List[String]) -> List[List[String]] {
  return words
    |> group_by(|w| sorted_key(w))
    |> filter(|g| len(g.1) >= 3)
    |> map(|g| g.1)
}

export function anagram_groups(words: string[]): string[][] {
  const groups = new Map<string, string[]>();
  for (const w of words) {
    const k = [...w].sort().join("");
    const g = groups.get(k);
    if (g) g.push(w);
    else groups.set(k, [w]);
  }
  return [...groups.values()].filter((g) => g.length >= 1);
}

