class _GameError(Exception):
    pass


def _roll(rolls: list[int], i: int) -> int:
    if i >= len(rolls):
        raise _GameError("incomplete game")
    return rolls[i]


def _frame_starts(rolls: list[int]) -> list[int]:
    """Validate the game frame by frame and return the index where each frame starts."""
    starts: list[int] = []
    i = 0
    for frame in range(1, 10):
        starts.append(i)
        if _roll(rolls, i) == 10:
            i += 1
            continue
        if _roll(rolls, i) + _roll(rolls, i + 1) > 10:
            raise _GameError(f"too many pins in frame {frame}")
        i += 2

    starts.append(i)
    first = _roll(rolls, i)
    if first == 10:
        bonus1, bonus2 = _roll(rolls, i + 1), _roll(rolls, i + 2)
        if bonus1 != 10 and bonus1 + bonus2 > 10:
            raise _GameError("too many pins in frame 10")
        i += 3
    else:
        second = _roll(rolls, i + 1)
        if first + second > 10:
            raise _GameError("too many pins in frame 10")
        if first + second == 10:
            _roll(rolls, i + 2)
            i += 3
        else:
            i += 2
    if i < len(rolls):
        raise _GameError("too many rolls")
    return starts


def bowling_score(rolls: list[int]) -> Ok[int] | Err:
    """Validate and score a complete ten-pin bowling game."""
    if any(roll < 0 or roll > 10 for roll in rolls):
        return {"ok": False, "error": "invalid roll"}
    try:
        starts = _frame_starts(rolls)
    except _GameError as exc:
        return {"ok": False, "error": str(exc)}

    total = 0
    for i in starts[:9]:
        if rolls[i] == 10:
            total += 10 - rolls[i + 1] + rolls[i + 2]
        elif rolls[i] + rolls[i + 1] == 10:
            total += 10 + rolls[i + 2]
        else:
            total += rolls[i] + rolls[i + 1]
    total += sum(rolls[starts[9]:])
    return {"ok": True, "value": total}

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bowling_score(rolls: number[]): Result<number> {
  const fail = (error: string): Result<number> => ({ ok: false, error });
  if (rolls.some((r) => r < 0 || r > 10)) return fail("invalid roll");
  let i = 0;
  let score = 0;
  const at = (k: number) => rolls[k];
  for (let frame = 1; frame <= 9; frame++) {
    if (i >= rolls.length) return fail("incomplete game");
    if (at(i) === 10) {
      i += 1;
      continue;
    }
    if (i + 1 >= rolls.length) return fail("incomplete game");
    if (at(i) + at(i + 1) > 10) return fail("too many pins in frame " + frame);
    i += 2;
  }
  // frame 10
  if (i + 1 >= rolls.length) return fail("incomplete game");
  let tenth: number;
  if (at(i) === 10) {
    if (i + 2 >= rolls.length) return fail("incomplete game");
    if (at(i + 1) !== 10 && at(i + 1) + at(i + 2) > 10) return fail("too many pins in frame 10");
    tenth = 3;
  } else {
    if (at(i) + at(i + 1) > 10) return fail("too many pins in frame 10");
    if (at(i) + at(i + 1) === 10) {
      if (i + 2 >= rolls.length) return fail("incomplete game");
      tenth = 3;
    } else tenth = 2;
  }
  if (i + tenth < rolls.length) return fail("too many rolls");
  // scoring
  let k = 0;
  for (let frame = 1; frame <= 9; frame++) {
    if (rolls[k] === 10) {
      score += 10 - rolls[k + 1] + rolls[k + 2];
      k += 1;
    } else if (rolls[k] + rolls[k + 1] === 10) {
      score += 10 + rolls[k + 2];
      k += 2;
    } else {
      score += rolls[k] + rolls[k + 1];
      k += 2;
    }
  }
  for (; k < rolls.length; k++) score += rolls[k];
  return { ok: true, value: score };
}

