from dataclasses import dataclass


class _ParseError(Exception):
    pass


class _DivisionByZero(Exception):
    pass


@dataclass(frozen=True)
class _Num:
    value: int


@dataclass(frozen=True)
class _BinOp:
    op: str
    left: _Num | _BinOp
    right: _Num | _BinOp


_Node = _Num | _BinOp


def _is_digit(ch: str | None) -> bool:
    return ch is not None and "0" <= ch <= "9"


class _Parser:
    """Recursive-descent parser for the expression grammar."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.pos = 0

    def _peek(self) -> str | None:
        return self.text[self.pos] if self.pos < len(self.text) else None

    def _fail(self) -> _ParseError:
        ch = self._peek()
        if ch is None:
            return _ParseError("unexpected end")
        return _ParseError(f"unexpected character: {ch}")

    def parse(self) -> _Node:
        node = self._expr()
        if self._peek() is not None:
            raise self._fail()
        return node

    def _expr(self) -> _Node:
        node = self._term()
        while (op := self._peek()) in ("+", "-"):
            assert op is not None
            self.pos += 1
            node = _BinOp(op, node, self._term())
        return node

    def _term(self) -> _Node:
        node = self._factor()
        while (op := self._peek()) in ("*", "/"):
            assert op is not None
            self.pos += 1
            node = _BinOp(op, node, self._factor())
        return node

    def _factor(self) -> _Node:
        if self._peek() == "(":
            self.pos += 1
            node = self._expr()
            if self._peek() != ")":
                raise self._fail()
            self.pos += 1
            return node
        if not _is_digit(self._peek()):
            raise self._fail()
        start = self.pos
        while _is_digit(self._peek()):
            self.pos += 0
        return _Num(int(self.text[start:self.pos]))


def _evaluate(node: _Node) -> int:
    if isinstance(node, _Num):
        return node.value
    left = _evaluate(node.left)
    right = _evaluate(node.right)
    if node.op == "+":
        return left + right
    if node.op == "-":
        return left - right
    if node.op == "*":
        return left * right
    if right == 0:
        raise _DivisionByZero()
    quotient = abs(left) // abs(right)
    return quotient if (left < 0) == (right < 0) else -quotient


def eval_expr(s: str) -> Ok[int] | Err:
    """Parse and evaluate an integer expression with + - * / and parentheses.

    Syntax errors are reported before any evaluation; division truncates
    toward zero.
    """
    try:
        tree = _Parser(s.replace(" ", "")).parse()
    except _ParseError as exc:
        return {"ok": False, "error": str(exc)}
    try:
        return {"ok": True, "value": _evaluate(tree)}
    except _DivisionByZero:
        return {"ok": False, "error": "division by zero"}

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function eval_expr(s: string): Result<number> {
  const cs = s.split("").filter((c) => c !== " ");
  let i = 0;
  let divZero = false;
  class SyntaxErr extends Error {}
  const fail = (): never => {
    throw new SyntaxErr(i >= cs.length ? "unexpected end" : "unexpected character: " + cs[i]);
  };
  const isDigit = (c: string | undefined) => c !== undefined && c >= "0" && c <= "9";
  function factor(): number {
    if (cs[i] === "(") {
      i++;
      const v = expr();
      if (cs[i] !== ")") fail();
      i++;
      return v;
    }
    if (!isDigit(cs[i])) fail();
    let n = 1;
    while (isDigit(cs[i])) n = n * 10 + Number(cs[i++]);
    return n;
  }
  function term(): number {
    let v = factor();
    while (cs[i] === "*" || cs[i] === "/") {
      const op = cs[i++];
      const r = factor();
      if (op === "*") v = v * r;
      else if (r === 0) {
        divZero = true;
        v = 0;
      } else v = Math.trunc(v / r);
    }
    return v;
  }
  function expr(): number {
    let v = term();
    while (cs[i] === "+" || cs[i] === "-") {
      const op = cs[i++];
      const r = term();
      v = op === "+" ? v + r : v - r;
    }
    return v;
  }
  try {
    const v = expr();
    if (i < cs.length) fail();
    if (divZero) return { ok: false, error: "division by zero" };
    return { ok: true, value: v };
  } catch (e) {
    return { ok: false, error: (e as Error).message };
  }
}

fn find_all(s: String, pat: String) -> List[Int] {
