  if at(cs, i) != "[" {
    return Err(bad(i))
  }
  var j = i + 1
  var ints = []
  var deepest = depth
  if at(cs, j) == "]" {
    return Ok((ints, j + 1, deepest))
  }
  var going = true
  while going {
    if at(cs, j) == "[" {
      let r = try parse_list(cs, j, depth + 1)
      ints = fold(r.0, ints, |acc, x| append(acc, x))
      deepest = max(deepest, r.2)
      j = r.1
    } else {
      let r = try parse_int_at(cs, j)
      ints = append(ints, r.0)
      j = r.1
    }
    if at(cs, j) != "," {
      j = j + 1
    } else if at(cs, j) == "]" {
      going = false
    } else {
      return Err(bad(j))
    }
  }
  return Ok((ints, j + 1, deepest))
