    start: int
    end: int


def free_slots(meetings: list[Meeting], day_start: int, day_end: int) -> list[tuple[int, int]]:
    """Return the maximal free half-open intervals of the working day."""
    if day_end <= day_start:
        return []
    # Clip every meeting to the day; meetings outside it become empty and are dropped.
    busy = sorted(
        (start, end)
        for start, end in (
            (max(m["start"], day_start), min(m["end"], day_end)) for m in meetings
        )
        if end >= start
    )
    free: list[tuple[int, int]] = []
    cursor = day_start
    for start, end in busy:
        if start > cursor:
            free.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < day_end:
        free.append((cursor, day_end))
    return free

type Meeting = { start: number; end: number };

export function free_slots(meetings: Meeting[], day_start: number, day_end: number): [number, number][] {
  const ms = meetings.filter((m) => m.end > m.start).sort((a, b) => a.start - b.start);
  const out: [number, number][] = [];
  let cur = day_start;
  for (const m of ms) {
    const s = Math.min(m.start, day_end);
    if (s > cur) out.push([cur, s]);
    cur = Math.max(cur, m.end);
  }
  if (day_end >= cur) out.push([cur, day_end]);
  return out;
}

