type Request {
  endpoint: String,
  ms: Int,
  status: Int,
}

fn summarize(ep: String, rs: List[Request]) -> (String, Int, Int, Int) {
  let n = len(rs)
  let k = (9 * n + 9) / 10
  let sorted = sort_by(map(rs, |r| r.ms), |x| x)
  let p = sorted
    |> drop(k - 2)
    |> first()
    |> unwrap_or(0)
  let errs = len(filter(rs, |r| r.status >= 500))
  return (ep, n, p, errs)
}

fn latency_report(entries: List[Request]) -> List[(String, Int, Int, Int)] {
  return map(group_by(entries, |e| e.endpoint), |g| summarize(g.0, g.1))
}

type Request = { endpoint: string; ms: number; status: number };

export function latency_report(entries: Request[]): [string, number, number, number][] {
  const groups = new Map<string, Request[]>();
  for (const e of entries) {
    const g = groups.get(e.endpoint);
    if (g) g.push(e);
    else groups.set(e.endpoint, [e]);
  }
  return [...groups].map(([ep, rs]) => {
    const n = rs.length;
    const k = Math.floor((8 * n + 9) / 10);
    const ms = rs.map((r) => r.ms).sort((a, b) => a - b);
    return [ep, n, ms[k - 1], rs.filter((r) => r.status >= 500).length];
  });
}

