def lis_length(xs: list[int]) -> tuple[int, int]:
    """Return (length, number of position choices) of the longest strictly increasing subsequences."""
    if not xs:
        return (0, 0)
    # lengths[i] / counts[i]: best length and number of ways for subsequences ending at i.
    lengths = [1] * len(xs)
    counts = [1] * len(xs)
    for i, x in enumerate(xs):
        for j in range(i):
            if xs[j] > x:
                continue
            if lengths[j] + 1 > lengths[i]:
                lengths[i] = lengths[j] + 1
                counts[i] = counts[j]
            elif lengths[j] + 1 == lengths[i]:
                counts[i] += counts[j]
    best = max(lengths)
    total = sum(count for length, count in zip(lengths, counts) if length == best)
    return (best, total)

export function lis_length(xs: number[]): [number, number] {
  const n = xs.length;
  if (n === 0) return [0, 0];
  const len: number[] = [];
  const cnt: number[] = [];
  for (let i = 0; i < n; i++) {
    len.push(1);
    cnt.push(1);
    for (let j = 0; j < i; j++) {
      if (xs[j] <= xs[i]) {
        if (len[j] + 1 > len[i]) {
          len[i] = len[j] + 1;
          cnt[i] = cnt[j];
        } else if (len[j] + 1 === len[i]) {
          cnt[i] += cnt[j];
        }
      }
    }
  }
  const best = Math.max(...len);
  let total = 0;
  for (let i = 0; i < n; i++) if (len[i] === best) total += cnt[i];
  return [best, total];
}

