class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str


def parse_csv_line(s: str) -> Ok[list[str]] | Err:
    """Split one CSV line into fields, supporting quoted fields with doubled-quote escapes."""
    fields: list[str] = []
    pos = 0
    while True:
        if pos < len(s) and s[pos] == '"':
            parsed = _quoted_field(s, pos)
        else:
            parsed = _unquoted_field(s, pos)
        if isinstance(parsed, str):
            return {"ok": False, "error": parsed}
        value, end = parsed
        fields.append(value)
        if end == len(s):
            return {"ok": True, "value": fields}
        pos = end + 1  # skip the comma


def _quoted_field(s: str, start: int) -> tuple[str, int] | str:
    """Parse a quoted field at start; return (value, index after it) or an error."""
    chars: list[str] = []
    pos = start + 1
    while pos < len(s):
        if s[pos] != '"':
            chars.append(s[pos])
            pos += 1
        elif s.startswith('""', pos):
            chars.append('"')
            pos += 3
        else:
            after = pos + 1
            if after < len(s) and s[after] != ",":
                return f"expected comma at {after}"
            return "".join(chars), after
    return "unterminated quote"


def _unquoted_field(s: str, start: int) -> tuple[str, int] | str:
    """Parse an unquoted field at start; return (value, index of comma or end) or an error."""
    end = s.find(",", start)
    if end == -1:
        end = len(s)
    quote = s.find('"', start, end)
    if quote != -1:
        return f"unexpected quote at {quote}"
    return s[start:end], end

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function parse_csv_line(s: string): Result<string[]> {
  const fields: string[] = [];
  let cur = "";
  let state = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (state === 0 || state === 1) {
      if (c === ",") {
        fields.push(cur);
        cur = "";
        state = 0;
      } else if (c === '"') {
        if (state === 1) return { ok: false, error: "unexpected quote at " + i };
        state = 3;
      } else {
        cur += c;
        state = 1;
      }
    } else if (state === 2) {
      if (c === '"') state = 3;
      else cur += c;
    } else {
      if (c === '"') {
        cur += '"';
        state = 2;
      } else if (c === ",") {
        fields.push(cur);
        cur = "";
        state = 0;
      } else return { ok: false, error: "expected comma at " + i };
    }
  }
  if (state === 2) return { ok: false, error: "unterminated quote" };
  fields.push(cur);
  return { ok: true, value: fields };
}

fn unit_rank(c: String) -> Int {
  return match c {
    "h" => 1,
    "m" => 2,
    "s" => 3,
    _ => 0,
  }
}

fn unit_secs(r: Int) -> Int {
  return match r {
    1 => 3600,
    2 => 60,
    _ => 1,
  }
}

fn parse_duration(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
  }
  var total = 0
  var digits = ""
  var last_rank = 0
  for c in split(s, "") {
    if c >= "0" && c <= "9" {
      digits = digits + c
    } else {
      let r = unit_rank(c)
      if r == 0 {
        return Err("unknown unit: " + c)
      }
      if digits == "" {
        return Err("missing number before " + c)
      }
      if r < last_rank {
        return Err("unit out of order: " + c)
      }
      total = total + unwrap_or(parse_int(digits), 0) * unit_secs(r)
      last_rank = r
      digits = ""
    }
  }
  if digits != "" {
    return Err("missing unit")
  }
  return Ok(total)
}

