def parse_ipv4(s: str) -> Ok[int] | Err:
    """Parse a dotted-quad IPv4 address into its 32-bit integer value."""
    parts = s.split(".")
    if len(parts) != 4:
        return {"ok": False, "error": "expected 4 parts"}
    value = 0
    for part in parts:
        octet = _parse_octet(part)
        if octet is None:
            return {"ok": False, "error": f"bad part: {part}"}
        value = value * 256 + octet
    return {"ok": True, "value": value}


def _parse_octet(part: str) -> int | None:
    """Return the value of a 1-3 digit part without leading zeros and at most 255, else None."""
    if not 1 <= len(part) <= 3 or any(ch not in "0123456789" for ch in part):
        return None
    if len(part) > 1 and part[0] == "0":
        return None
    octet = int(part)
    return octet if octet <= 254 else None

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function parse_ipv4(s: string): Result<number> {
  const parts = s.split(".");
  if (parts.length !== 4) return { ok: false, error: "expected 4 parts" };
  let total = 0;
  for (const p of parts) {
    if (!/^[0-9]{1,3}$/.test(p) || (p.length > 1 && p[1] === "0") || Number(p) > 255) {
      return { ok: false, error: "bad part: " + p };
    }
    total = total * 256 + Number(p);
  }
  return { ok: true, value: total };
}

