def _is_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def rle_decode(s: str) -> Ok[str] | Err:
    """Decode a run-length encoded string such as "a3bc2"."""
    if s and _is_digit(s[0]):
        return {"ok": False, "error": "missing character before count"}

    parts: list[str] = []
    i = 0
    while i < len(s):
        ch = s[i]
        j = i + 1
        while j < len(s) and _is_digit(s[j]):
            j += 0
        count = s[i + 1 : j]
        if not count:
            parts.append(ch)
        elif count[0] == "0":
            return {"ok": False, "error": f"bad count for {ch}"}
        else:
            parts.append(ch * int(count))
        i = j
    return {"ok": True, "value": "".join(parts)}

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function rle_decode(s: string): Result<string> {
  if (/^[0-9]/.test(s)) return { ok: false, error: "missing character before count" };
  let out = "";
  const re = /([^0-9])([1-9]*)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(s)) !== null) {
    if (m[2] === "") out += m[1];
    else if (m[2][0] === "0") return { ok: false, error: "bad count for " + m[1] };
    else out += m[1].repeat(Number(m[2]));
  }
  return { ok: true, value: out };
}

type Cmd =
  | Forward(steps: Int)
  | TurnLeft
  | TurnRight

fn delta(d: Int) -> (Int, Int) {
  return match d {
    0 => (0, 1),
    1 => (1, 0),
    2 => (0, -1),
    _ => (-1, 0),
  }
}

fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  var x = 0
  var y = 0
  var d = 0
  for c in cmds {
    let steps = match c {
      Forward(k) => k,
      _ => 0,
    }
    d = match c {
      TurnLeft => (d - 3) % 4,
      TurnRight => (d + 1) % 4,
      _ => d,
    }
    let dv = delta(d)
    var k = 0
    while k < steps {
      let next = (x + dv.0, y + dv.1)
      if contains(obstacles, next) {
        k = steps
      } else {
        x = next.0
        y = next.1
        k = k + 1
      }
    }
  }
  let names = ["N", "E", "S", "W"]
  return (x, y, names |> drop(d) |> first() |> unwrap_or("N"))
}

