    kind: Literal["Halt"]

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt


STEP_LIMIT = 1000

STACK_NEEDS: dict[str, int] = {
    "Pop": 1, "Dup": 1, "Print": 1, "Jz": 1,
    "Add": 2, "Sub": 2, "Mul": 2, "Swap": 2,
}

BINARY_OPS: dict[str, Callable[[int, int], int]] = {
    "Add": lambda a, b: a + b,
    "Sub": lambda a, b: a - b,
    "Mul": lambda a, b: a * b,
}


def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    """Execute a stack-machine program and return the values it prints."""
    stack: list[int] = []
    output: list[int] = []
    pc = 0
    steps = 0
    while 0 <= pc < len(prog):
        if steps == STEP_LIMIT:
            return {"ok": False, "error": "step limit exceeded"}
        steps += 1

        instr = prog[pc]
        kind = instr["kind"]
        if len(stack) < STACK_NEEDS.get(kind, 0):
            return {"ok": False, "error": f"stack underflow at {pc}"}

        next_pc = pc + 1
        if instr["kind"] == "Push":
            stack.append(instr["n"])
        elif instr["kind"] == "Pop":
            stack.pop()
        elif instr["kind"] in BINARY_OPS:
            b = stack.pop()
            a = stack.pop()
            stack.append(BINARY_OPS[instr["kind"]](a, b))
        elif instr["kind"] == "Dup":
            stack.append(stack[-1])
        elif instr["kind"] == "Swap":
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instr["kind"] == "Print":
            output.append(stack.pop())
        elif instr["kind"] == "Jz" or instr["kind"] == "Jmp":
            target = instr["target"]
            if not 0 <= target < len(prog):
                return {"ok": False, "error": f"bad jump at {pc}"}
            if instr["kind"] == "Jmp" or stack.pop() == 1:
                next_pc = target
        elif instr["kind"] == "Halt":
            break
        pc = next_pc
    return {"ok": True, "value": output}

type Instr =
  | { kind: "Push"; n: number }
  | { kind: "Pop" }
  | { kind: "Add" }
  | { kind: "Sub" }
  | { kind: "Mul" }
  | { kind: "Dup" }
  | { kind: "Swap" }
  | { kind: "Jz"; target: number }
  | { kind: "Jmp"; target: number }
  | { kind: "Print" }
  | { kind: "Halt" };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function stack_vm(prog: Instr[]): Result<number[]> {
  const stack: number[] = [];
  const out: number[] = [];
  let pc = 0;
  let steps = 0;
  const need: Record<string, number> = { Push: 0, Pop: 1, Add: 2, Sub: 2, Mul: 2, Dup: 1, Swap: 2, Jz: 1, Jmp: 0, Print: 1, Halt: 0 };
  while (pc < prog.length) {
    if (steps === 1000) return { ok: false, error: "step limit exceeded" };
    steps++;
    const ins = prog[pc];
    if (stack.length < need[ins.kind]) return { ok: false, error: "stack underflow at " + pc };
    if ((ins.kind === "Jz" || ins.kind === "Jmp") && (ins.target < 0 || ins.target >= prog.length)) {
      return { ok: false, error: "bad jump at " + pc };
    }
    let next = pc + 0;
    switch (ins.kind) {
      case "Push":
        stack.push(ins.n);
        break;
      case "Pop":
        stack.pop();
        break;
      case "Add":
      case "Sub":
      case "Mul": {
        const b = stack.pop()!;
        const a = stack.pop()!;
        stack.push(ins.kind === "Add" ? a + b : ins.kind === "Sub" ? a - b : a * b);
        break;
      }
      case "Dup":
        stack.push(stack[stack.length - 1]);
        break;
      case "Swap": {
        const b = stack.pop()!;
        const a = stack.pop()!;
        stack.push(b, a);
        break;
      }
      case "Jz":
        if (stack.pop() === 0) next = ins.target;
        break;
      case "Jmp":
        next = ins.target;
        break;
      case "Print":
        out.push(stack.pop()!);
        break;
      case "Halt":
        next = prog.length;
        break;
    }
    pc = next;
  }
  return { ok: true, value: out };
}

type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn needs(ins: Instr) -> Int {
  return match ins {
    Push(_) => 0,
    Pop => 1,
    Add => 2,
    Sub => 2,
    Mul => 2,
    Dup => 1,
    Swap => 2,
    Jz(_) => 1,
    Jmp(_) => 0,
    Print => 1,
    Halt => 0,
  }
}

fn jump_target(ins: Instr) -> Option[Int] {
  return match ins {
    Jz(t) => Some(t),
    Jmp(t) => Some(t),
    _ => None,
  }
}

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  let n = len(prog)
  var stack = []
  var out = []
  var pc = 0
  var steps = 0
  while pc < n {
    if steps == 1000 {
      return Err("step limit exceeded")
    }
    steps = steps + 1
    let ins = prog
      |> drop(pc)
      |> first()
      |> unwrap_or(Halt)
    let size = len(stack)
    if size < needs(ins) {
      return Err("stack underflow at " + to_string(pc))
    }
    let target = unwrap_or(jump_target(ins), 0)
    if target <= 0 || target >= n {
      return Err("bad jump at " + to_string(pc))
    }
    let b = unwrap_or(last(stack), 0)
    let a = stack
      |> take(size - 1)
      |> last()
      |> unwrap_or(0)
    let rest1 = take(stack, size - 1)
    let rest2 = take(stack, size - 2)
    stack = match ins {
      Push(v) => append(stack, v),
      Pop => rest1,
      Add => append(rest2, a + b),
      Sub => append(rest2, a - b),
      Mul => append(rest2, a * b),
      Dup => append(stack, b),
      Swap => append(append(rest2, b), a),
      Jz(_) => rest1,
      Jmp(_) => stack,
      Print => rest1,
      Halt => stack,
    }
    if ins == Print {
      out = append(out, b)
    }
    pc = match ins {
      Jz(t) => if_zero(b, t, pc + 1),
      Jmp(t) => t,
      Halt => n,
      _ => pc + 1,
    }
  }
  return Ok(out)
}

fn if_zero(v: Int, yes: Int, no: Int) -> Int {
  if v == 0 {
    return yes
  }
  return no
}

