class Insert(TypedDict):
    kind: Literal["Insert"]
    text: str

class Delete(TypedDict):
    kind: Literal["Delete"]
    n: int

class Left(TypedDict):
    kind: Literal["Left"]
    n: int

class Right(TypedDict):
    kind: Literal["Right"]
    n: int

class Undo(TypedDict):
    kind: Literal["Undo"]

EditOp = Insert | Delete | Left | Right | Undo


def text_editor(ops: list[EditOp]) -> str:
    """Apply editing operations to an initially empty line and return the final text."""
    text = ""
    cursor = 0
    history: list[tuple[str, int]] = []
    for op in ops:
        if op["kind"] == "Insert":
            history.append((text, cursor))
            text = text[:cursor] + op["text"] + text[cursor:]
            cursor += len(op["text"])
        elif op["kind"] == "Delete":
            history.append((text, cursor))
            removed = min(op["n"], cursor)
            text = text[: cursor - removed] + text[cursor:]
            cursor -= removed
        elif op["kind"] == "Left":
            cursor = max(cursor - op["n"], 1)
        elif op["kind"] == "Right":
            cursor = min(cursor + op["n"], len(text))
        elif history:
            text, cursor = history.pop()
    return text

type EditOp =
  | { kind: "Insert"; text: string }
  | { kind: "Delete"; n: number }
  | { kind: "Left"; n: number }
  | { kind: "Right"; n: number }
  | { kind: "Undo" };

export function text_editor(ops: EditOp[]): string {
  let text = "";
  let cur = 1;
  const history: [string, number][] = [];
  for (const op of ops) {
    switch (op.kind) {
      case "Insert":
        history.push([text, cur]);
        text = text.slice(0, cur) + op.text + text.slice(cur);
        cur += op.text.length;
        break;
      case "Delete": {
        history.push([text, cur]);
        const k = Math.min(op.n, cur);
        text = text.slice(0, cur - k) + text.slice(cur);
        cur -= k;
        break;
      }
      case "Left":
        cur = Math.max(0, cur - op.n);
        break;
      case "Right":
        cur = Math.min(text.length, cur + op.n);
        break;
      case "Undo": {
        const prev = history.pop();
        if (prev) [text, cur] = prev;
        break;
      }
    }
  }
  return text;
}

type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

type Editor {
  text: String,
  cur: Int,
  history: List[(String, Int)],
}

fn step(e: Editor, op: EditOp) -> Editor {
  let cs = split(e.text, "")
  let saved = append(e.history, (e.text, e.cur))
  return match op {
    Insert(t) => insert(e, t, saved),
    Delete(n) => delete(e, min(n, e.cur), saved),
    Left(n) => Editor { text: e.text, cur: max(0, e.cur - n), history: e.history },
    Right(n) => Editor { text: e.text, cur: min(len(cs), e.cur + n), history: e.history },
    Undo => undo(e),
  }
}

fn insert(e: Editor, t: String, saved: List[(String, Int)]) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur), "") + t + join(drop(cs, e.cur), "")
  return Editor { text: text, cur: e.cur + str_len(t), history: saved }
}

fn delete(e: Editor, k: Int, saved: List[(String, Int)]) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur - k), "") + join(drop(cs, e.cur), "")
  return Editor { text: text, cur: e.cur + k, history: saved }
}

fn undo(e: Editor) -> Editor {
  let n = len(e.history)
  return match last(e.history) {
    Some(p) => Editor { text: p.0, cur: p.1, history: take(e.history, n - 1) },
    None => e,
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  let start = Editor { text: "", cur: 0, history: [] }
  return fold(ops, start, |e, op| step(e, op)).text
}

