      i = j;
    } else if (["==", "<=", ">=", "!="].includes(two)) {
      out.push({ kind: "Sym", text: two });
      i += 2;
    } else if ("+-*/=<>(),".includes(c)) {
      out.push({ kind: "Sym", text: c });
      i++;
    } else return { ok: false, error: "unexpected character: " + c + " at " + i };
  }
  return { ok: true, value: out };
}

